mapper.update:
UPDATE `order`
SET status = #{toStatus}, update_time = NOW()
WHERE id = #{id} AND status = #{fromStatus}

mapper.select:
SELECT 
FROM `order`
WHERE status = #{status}
  AND expire_time < #{expireTime}
LIMIT #{limit}

SELECT 
FROM `order`
WHERE status = #{status}
  AND update_time < #{updateBefore}
ORDER BY update_time ASC
LIMIT #{limit}

SELECT 
FROM `order`
WHERE user_id = #{userId}
AND status = #{status}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
ORDER BY create_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM `order`
WHERE user_id = #{userId}
AND status = #{status}
AND create_time >= #{startTime}
AND create_time <= #{endTime}

SELECT 
FROM `order` o
JOIN show_session ss ON ss.id = o.session_id AND ss.show_id = #{showId}

    AND o.session_id = #{sessionId}
    AND o.order_no = #{orderNo}
    AND o.status = #{status}
    AND o.create_time >= #{startTime}
    AND o.create_time <= #{endTime}

ORDER BY o.create_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM `order` o
JOIN show_session ss ON ss.id = o.session_id AND ss.show_id = #{showId}

    AND o.session_id = #{sessionId}
    AND o.order_no = #{orderNo}
    AND o.status = #{status}
    AND o.create_time >= #{startTime}
    AND o.create_time <= #{endTime}
